 as $role)<option value="{{ $role->id }}" @selected($transition->responsible_role_id==$role->id)>{{ $role->name }}</option>@endforeach</select></div><div class="form-group col-md-6 mb-0"><label>Action capability</label><select name="transitions[{{ $i }}][required_permission]" class="custom-select"><option value="">No additional capability</option>@foreach($permissions as $permission)<option value="{{ $permission->slug }}" @selected($transition->required_permission===$permission->slug)>{{ $permission->name }}@if($permission->slug) · {{ $permission->slug }}@endif</option>@endforeach</select></div><div class="form-group col-md-6 mb-0"><label class="d-block">Comment</label><label class="mb-0"><input type="checkbox" name="transitions[{{ $i }}][requires_comment]" value="1" @checked($transition->requires_comment)> Require a comment</label></div></div></div>
