@push('scripts')<script>
(function(){
const stageList=document.getElementById('stage-list'), transitionList=document.getElementById('transition-list'), startSelect=document.getElementById('starting-stage');
const roles=@json($roles->map(fn($r)=>['id'=>$r->id,'name'=>$r->name])->values());
const permissions=@json($permissions->map(fn($p)=>['slug'=>$p->slug,'name'=>$p->name])->values());
const actions=@json($actions->values());
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const roleOptions=(selected='')=>'<option value="">Any authorized role</option>'+roles.map(r=>`<option value="${r.id}" ${String(selected)===String(r.id)?'selected':''}>${esc(r.name)}</option>`).join('');
const permissionOptions=(selected='')=>'<option value="">No additional capability</option>'+permissions.map(p=>`<option value="${esc(p.slug)}" ${selected===p.slug?'selected':''}>${esc(p.name)} · ${esc(p.slug)}</option>`).join('');
const actionOptions=(selected='FORWARD')=>actions.map(a=>`<option value="${a}" ${selected===a?'selected':''}>${esc(a.replaceAll('_',' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()))}</option>`).join('');
function stages(){return [...stageList.querySelectorAll('.stage-row')].map(row=>({code:row.querySelector('.stage-code')?.value||'',name:row.querySelector('.stage-name')?.value||'Unnamed stage'})).filter(s=>s.code);}
function options(selected=''){return stages().map(s=>`<option value="${esc(s.code)}" ${selected===s.code?'selected':''}>${esc(s.name)}</option>`).join('');}
function reindex(){stageList.querySelectorAll('.stage-row').forEach((row,i)=>{row.querySelector('.clay-step').textContent=i+1; row.querySelectorAll('[name]').forEach(el=>el.name=el.name.replace(/stages\[\d+\]/,`stages[${i}]`));});transitionList.querySelectorAll('.transition-row').forEach((row,i)=>row.querySelectorAll('[name]').forEach(el=>el.name=el.name.replace(/transitions\[\d+\]/,`transitions[${i}]`)));refreshTransitionOptions();refreshStartingOptions();}
function refreshStartingOptions(){const current=startSelect.value; startSelect.innerHTML=options(current); if([...startSelect.options].some(o=>o.value===current)) startSelect.value=current; updateStartBadges();}
function updateStartBadges(){stageList.querySelectorAll('.stage-row').forEach(row=>{let badge=row.querySelector('.clay-start-badge');const selected=row.querySelector('.stage-code')?.value===startSelect.value;if(selected&&!badge){badge=document.createElement('span');badge.className='clay-start-badge';badge.textContent='Starting';row.querySelector('.clay-stage-title').appendChild(badge);}if(!selected&&badge)badge.remove();});}
function refreshTransitionOptions(){transitionList.querySelectorAll('.transition-row').forEach(row=>{const from=row.querySelector('.from-code'),to=row.querySelector('.to-code'),fromVal=from.value,toVal=to.value;from.innerHTML=options(fromVal);to.innerHTML=options(toVal);from.value=fromVal;to.value=toVal;updateFlow(row);});}
function updateFlow(row){const from=row.querySelector('.from-code'),to=row.querySelector('.to-code'),action=row.querySelector('.label-input');const fromLabel=row.querySelector('.from-label'),toLabel=row.querySelector('.to-label'),actionLabel=row.querySelector('.action-label');if(fromLabel)fromLabel.textContent=from?.selectedOptions[0]?.text||'From stage';if(toLabel)toLabel.textContent=to?.selectedOptions[0]?.text||'To stage';if(actionLabel)actionLabel.textContent=action?.value||'Action';}
function addStage(){const i=stageList.querySelectorAll('.stage-row').length;const row=document.createElement('div');row.className='clay-stage stage-row';row.innerHTML=`<div class="clay-stage-header"><div class="clay-stage-title"><span class="clay-step">${i+1}</span><span class="stage-heading">New stage</span></div><button type="button" class="btn btn-sm btn-light clay-btn-secondary remove-stage"><i class="fas fa-trash-alt"></i></button></div><div class="form-row"><div class="form-group col-md-6"><label>Stage name</label><input name="stages[${i}][name]" class="form-control stage-name" required></div><div class="form-group col-md-6"><label>Stage code</label><input name="stages[${i}][code]" class="form-control stage-code" required></div><div class="form-group col-md-6"><label>Responsible role</label><select name="stages[${i}][responsible_role_id]" class="custom-select">${roleOptions()}</select></div><div class="form-group col-md-6"><label>Stage capability</label><select name="stages[${i}][required_permission]" class="custom-select">${permissionOptions()}</select></div><div class="form-group col-md-6 mb-0"><label class="d-block">Stage type</label><label class="mb-0"><input type="checkbox" name="stages[${i}][is_terminal]" value="1"> Final stage</label></div></div>`;stageList.appendChild(row);reindex();}
function addTransition(){const i=transitionList.querySelectorAll('.transition-row').length;const list=stages();const first=list[0]?.code||'',second=list[1]?.code||first;const row=document.createElement('div');row.className='clay-transition transition-row';row.innerHTML=`<div class="clay-transition-header"><div class="clay-flow"><span class="clay-flow-pill from-label">${esc(list[0]?.name||'From stage')}</span><span class="clay-flow-arrow"><i class="fas fa-arrow-right"></i></span><span class="clay-flow-pill action-label">Forward</span><span class="clay-flow-arrow"><i class="fas fa-arrow-right"></i></span><span class="clay-flow-pill to-label">${esc(list[1]?.name||list[0]?.name||'To stage')}</span></div><button type="button" class="btn btn-sm btn-light clay-btn-secondary remove-transition"><i class="fas fa-trash-alt"></i></button></div><div class="form-row"><div class="form-group col-md-4"><label>From stage</label><select name="transitions[${i}][from_code]" class="custom-select from-code" required>${options(first)}</select></div><div class="form-group col-md-4"><label>Action</label><select name="transitions[${i}][action]" class="custom-select action-select" required>${actionOptions()}</select></div><div class="form-group col-md-4"><label>To stage</label><select name="transitions[${i}][to_code]" class="custom-select to-code" required>${options(second)}</select></div><div class="form-group col-md-6"><label>Action button label</label><input name="transitions[${i}][label]" class="form-control label-input" value="Forward" required></div><div class="form-group col-md-6"><label>Responsible role</label><select name="transitions[${i}][responsible_role_id]" class="custom-select">${roleOptions()}</select></div><div class="form-group col-md-6 mb-0"><label>Action capability</label><select name="transitions[${i}][required_permission]" class="custom-select">${permissionOptions()}</select></div><div class="form-group col-md-6 mb-0"><label class="d-block">Comment</label><label class="mb-0"><input type="checkbox" name="transitions[${i}][requires_comment]" value="1"> Require a comment</label></div></div>`;transitionList.appendChild(row);reindex();}
document.getElementById('add-stage')?.addEventListener('click',addStage);document.getElementById('add-transition')?.addEventListener('click',addTransition);stageList?.addEventListener('click',e=>{if(e.target.closest('.remove-stage')){if(stageList.querySelectorAll('.stage-row').length<=1)return;const row=e.target.closest('.stage-row');const was=row.querySelector('.stage-code')?.value===startSelect.value;row.remove();reindex();if(was)startSelect.value=startSelect.options[0]?.value||'';updateStartBadges();}});transitionList?.addEventListener('click',e=>{if(e.target.closest('.remove-transition'))e.target.closest('.transition-row').remove();reindex();});stageList?.addEventListener('input',e=>{if(e.target.matches('.stage-name,.stage-code')){e.target.closest('.stage-row').querySelector('.stage-heading').textContent=e.target.closest('.stage-row').querySelector('.stage-name').value||'New stage';refreshStartingOptions();}});startSelect?.addEventListener('change',updateStartBadges);transitionList?.addEventListener('input',e=>{if(e.target.matches('.label-input'))updateFlow(e.target.closest('.transition-row'));});
refreshStartingOptions();refreshTransitionOptions();
})();
</script>@endpush
@endsection
